import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Remove near-duplicates based on correlation
    keep = set()
    seen = set()
    for i, fid1 in enumerate(feats.ids):
        if fid1 in seen:
            continue
        keep.add(fid1)
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if fid2 in seen:
                continue
            corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(corr) >= 0.6:
                seen.add(fid2)

    # Filter to non-duplicate features
    filtered_ids = tuple(f for f in feats.ids if f in keep)

    # Find top features by t-statistic
    effects = []
    for i, fid in enumerate(filtered_ids):
        col_idx = feats.column(fid)
        # Use Welch's t-test statistic
        t_stat = stats.ttest_ind(
            feats.x[feats.y==1, col_idx],
            feats.x[feats.y==0, col_idx],
            equal_var=False
        )[0]
        effects.append((abs(t_stat), fid))

    # Sort by t-statistic (descending)
    effects.sort(reverse=True)

    # Select top drivers
    drivers = tuple(fid for _, fid in effects[:MAX_DRIVERS])

    # If no strong drivers, return empty
    if not drivers:
        return Design(
            drivers=(),
            columns=filtered_ids,
            products=(),
            loadings={}
        )

    # Return single driver with highest effect
    return Design(
        drivers=(drivers[0],),
        columns=filtered_ids,
        products=(),
        loadings={drivers[0]: 1.0}
    )
